{"id":"50900571-6872-44d2-a88d-e940fb7a1eff","slug":"v6-ingest-events","name":"v6-ingest-events","status":"ACTIVE","version":1,"created_at":1789623180254,"updated_at":1789623180254,"verify_jwt":true,"import_map":false,"entrypoint_path":"/tmp/user_fn_bgmtzwfafcgjklgygvtx_50900571-6872-44d2-a88d-e940fb7a1eff_1/source/supabase/functions/v6-ingest-events/index.ts","ezbr_sha256":"f36bccb9976b0a0fbce2f3bdc71561917c10d9e547b8671c51fd8f188275afb1","files":[{"name":"functions/v6-ingest-events/index.ts","content":"// Explicit additive import into shadow ledger; original source records are never changed.
import {createClient} from 'https://esm.sh/@supabase/supabase-js@2'
import {authorizeWithClients} from '../_shared/scoring-v6/authorization.ts'
import {normalizeMessage} from '../_shared/scoring-v6/adapters.ts'
import {checked} from '../_shared/scoring-v6/pipeline.ts'
Deno.serve(async(req)=>{
  const json=(b:unknown,s=200)=>new Response(JSON.stringify(b),{status:s,headers:{'Content-Type':'application/json'}})
  if(req.method!=='POST')return json({error:'Method not allowed'},405)
  const url=Deno.env.get('SUPABASE_URL')??'',key=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
  const db=createClient(url,key??''),user=createClient(url,Deno.env.get('SUPABASE_ANON_KEY')??'',{global:{headers:{Authorization:req.headers.get('authorization')??''}}})
  try{
    await authorizeWithClients(req,{},db,user,key)
    const body=await req.json()
    if(typeof body.organizationId!=='string')return json({error:'organizationId required'},400)
    let q=db.from('communication_messages').select('*,contacts(company_id)').eq('organization_id',body.organizationId).order('id').limit(100)
    if(body.after)q=q.gt('id',body.after)
    const rows=await checked<any[]>(q),at=new Date().toISOString()
    let imported=0,unattributed=0
    for(const row of rows){
      // First materialization is knowledge NOW, not fabricated knowledge in the past.
      const event=normalizeMessage({...row,account_id:row.contacts?.company_id,updated_at:at})
      if(!event){unattributed++;continue}
      await checked(db.rpc('v6_foundation_append',{p_dyad:event.dyad,p_kind:'event',p_payload:event}));imported++
    }
    return json({imported,unattributed,quality:'unknown_until_verified',next_after:rows.length===100?rows.at(-1).id:null})
  }catch(e){const error=e instanceof Error?e.message:String(e);return json({error},error==='UNAUTHORIZED'?401:error==='FORBIDDEN'?403:500)}
})
"},{"name":"functions/_shared/scoring-v6/authorization.ts","content":"/** Authentication adapter. Never decodes JWTs; user JWTs are verified by auth.getUser. */
export interface AuthorizationPorts {
  serviceKey: string | undefined
  cronSecret(): Promise<string|null>
  verifyUser(token:string): Promise<string|null>
  isMember(userId:string,organizationId:string): Promise<boolean>
  canReadContact(userId:string,organizationId:string,contactId:string): Promise<boolean>
}
export type Principal = {kind:'service';userId:null}|{kind:'user';userId:string}
export async function authorizeFoundationRequest(req: Request, scope: {organizationId?:string|null;contactId?:string|null}, ports:AuthorizationPorts): Promise<Principal> {
  const token = (req.headers.get('authorization') ?? '').replace(/^Bearer /,'')
  // Possession of the configured server credential, not a self-asserted JWT claim.
  if (ports.serviceKey && token === ports.serviceKey) return {kind:'service',userId:null}
  const supplied = req.headers.get('x-cron-secret')
  if (supplied) { const expected = await ports.cronSecret(); if (expected && supplied===expected) return {kind:'service',userId:null} }
  if (!token) throw new Error('UNAUTHORIZED')
  const userId = await ports.verifyUser(token)
  if (!userId) throw new Error('UNAUTHORIZED')
  if (!scope.organizationId || !await ports.isMember(userId,scope.organizationId)) throw new Error('FORBIDDEN')
  // Manual classification requires an explicit visible contact. No unrestricted org scans.
  if (!scope.contactId || !await ports.canReadContact(userId,scope.organizationId,scope.contactId)) throw new Error('FORBIDDEN')
  return {kind:'user',userId}
}
export async function authorizeWithClients(req:Request, scope:{organizationId?:string|null;contactId?:string|null}, admin:any, user:any, serviceKey:string|undefined) {
  return authorizeFoundationRequest(req,scope,{
    serviceKey,
    cronSecret:async()=>{ const r=await admin.from('app_secrets').select('value').eq('name','monitor_cron').maybeSingle(); if(r.error) throw r.error; return r.data?.value ?? null },
    verifyUser:async token=>{const r=await user.auth.getUser(token); return r.error ? null : r.data?.user?.id ?? null},
    isMember:async (uid,org)=>{const r=await user.from('memberships').select('id').eq('user_id',uid).eq('organization_id',org).maybeSingle(); return !r.error && !!r.data},
    canReadContact:async (_uid,org,id)=>{const r=await user.from('contacts').select('id').eq('id',id).eq('organization_id',org).maybeSingle(); return !r.error && !!r.data},
  })
}
"},{"name":"functions/_shared/scoring-v6/adapters.ts","content":"import type { RelationalEvent, DyadIdentity, IdentityQuality } from './foundation.ts'
import { dyadKey } from './foundation.ts'
/** Ingestion ownership is not proof of identity or participation. Missing quality stays unknown. */
export function normalizeMessage(row: Record<string, any>, identity: IdentityQuality = 'unknown'): RelationalEvent | null {
  const collaborator = row.source_owner_user_id ?? row.metadata?.user_id
  if (!row.organization_id || !row.contact_id || !collaborator || !row.id || !row.created_at) return null
  const dyad: DyadIdentity = {organizationId:row.organization_id,collaboratorUserId:collaborator,contactId:row.contact_id}
  return {id:`message:${row.id}:${collaborator}`,dyad,accountId:row.account_id ?? null,sourceEventId:String(row.external_message_id ?? row.id),sourceType:'communication_message',channel:String(row.provider ?? 'unknown'),
    eventTime:row.sent_at,ingestedAt:row.created_at,recordedAt:row.updated_at ?? row.created_at,effectiveFrom:row.sent_at,
    state:row.deleted_at ? 'deleted' : 'observed',internalActorId:collaborator,externalActorId:row.contact_id,participants:[collaborator,row.contact_id],ownerUserId:collaborator,
    evidenceRef:`communication_messages:${row.id}`,evidenceUnitId:`${row.provider}:${row.external_message_id ?? row.id}`,
    identityQuality:identity,completeness:row.ingestion_complete === true ? 'complete':'unknown',sourceVersion:'message-adapter-v1',participationObserved:true,direction:row.direction,threadId:row.thread_id}
}
export function normalizeMeeting(row: Record<string, any>, dyad: DyadIdentity): RelationalEvent | null {
  if (!row.id || !row.created_at || row.organization_id!==dyad.organizationId) return null
  return {id:`meeting:${row.id}:${dyadKey(dyad)}`,dyad,accountId:row.company_id ?? null,sourceEventId:row.id,sourceType:'meeting',channel:'meeting',eventTime:row.starts_at,ingestedAt:row.created_at,recordedAt:row.updated_at ?? row.created_at,effectiveFrom:row.starts_at,
    state:row.status==='cancelled' ? 'cancelled' : row.participation_observed===true ? 'observed':'scheduled',internalActorId:dyad.collaboratorUserId,externalActorId:dyad.contactId,participants:row.participant_ids ?? [],ownerUserId:row.owner_user_id,
    evidenceRef:`meetings:${row.id}`,evidenceUnitId:`meeting:${row.id}`,identityQuality:row.identity_quality ?? 'unknown',completeness:row.ingestion_complete===true ? 'complete':'unknown',sourceVersion:'meeting-adapter-v1',participationObserved:row.participation_observed===true}
}
/** No LIMIT 1 policy: ambiguity is a result, never an arbitrary person. */
export function resolveUniqueIdentity(ids: string[]): {contactId:string|null; quality:IdentityQuality} {
  const unique = [...new Set(ids)]
  return unique.length===1 ? {contactId:unique[0]!,quality:'verified'} : {contactId:null,quality:unique.length ? 'ambiguous':'unknown'}
}
"},{"name":"functions/_shared/scoring-v6/foundation.ts","content":"/** Canonical Phase 1 boundary. Pure, no database, no LLM, no current-time reads. */
import { calculateDyadScoreCore } from './calculateDyadScoreCore.ts'
import { statusFromCadence, RELIABILITY_PARAMS_V1 } from './snapshots.ts'
import type { AxisId, DyadRole, MarkerEvent, MarkerRegistry, ScoringParams, MarkerContribution } from './types.ts'
export const SCORING_VERSION = 'v6-foundation-1'
export type IdentityQuality = 'verified' | 'inferred' | 'ambiguous' | 'unknown'
export type Completeness = 'complete' | 'partial' | 'unknown' | 'error'
export type Voluntariness = 'spontaneous' | 'requested' | 'reactive' | 'forced' | 'unknown'
export interface DyadIdentity { organizationId: string; collaboratorUserId: string; contactId: string }
export function dyadKey(d: DyadIdentity): string {
  if (![d.organizationId, d.collaboratorUserId, d.contactId].every(x => typeof x === 'string' && x.trim())) throw new Error('INVALID_DYAD')
  return JSON.stringify([d.organizationId, d.collaboratorUserId, d.contactId])
}
export interface Revision { id: string; recordedAt: string; effectiveFrom: string; effectiveUntil?: string | null }
export interface RelationalEvent extends Revision {
  dyad: DyadIdentity; accountId: string | null; sourceEventId: string; sourceType: string; channel: string
  eventTime: string; ingestedAt: string; state: 'observed' | 'scheduled' | 'cancelled' | 'corrected' | 'deleted'
  internalActorId: string | null; externalActorId: string | null; participants: string[]; ownerUserId: string | null
  evidenceRef: string; evidenceUnitId: string; identityQuality: IdentityQuality; completeness: Completeness
  sourceVersion: string; evidenceText?: string; participationObserved: boolean; direction?: 'inbound' | 'outbound'; threadId?: string
}
export interface MarkerRevision extends Revision {
  dyad: DyadIdentity; markerId: string; sense: -1 | 1; observedAt: string
  sourceEventIds: string[]; state: 'active' | 'resolved' | 'superseded' | 'obsolete'
  resolvedAt?: string | null; supersededAt?: string | null
  criticalValidated?: boolean; evidenceQuote?: string
  status: 'accepted' | 'candidate'; registryVersion: string; detectorVersion: string
  voluntariness: Voluntariness; intensity: 'low' | 'medium' | 'high' | 'critical' | 'unknown'
}
export interface QualityRevision extends Revision {
  reliability: number | null; reliabilityEvidence: string[]; identity: IdentityQuality; diarization: IdentityQuality
  completeness: Completeness; expectedChannels: string[] | null; observedChannels: string[]
  periodStart: string | null; periodEnd: string | null
}
export interface RoleRevision extends Revision { origin: 'declared' | 'inferred'; role: DyadRole | null; authority: number | null; evidence: string[] }
export type ReplayMode = 'state_as_known_at_T' | 'historical_state_recomputed_with_current_truth'
export interface FoundationInput {
  dyad: DyadIdentity; at: string; computedAt: string; mode?: ReplayMode; knowledgeAt?: string
  events: RelationalEvent[]; markers: MarkerRevision[]; qualities: QualityRevision[]; roles: RoleRevision[]
  params: ScoringParams; registry: MarkerRegistry
}
const time = (s: string | null | undefined) => s ? Date.parse(s) : NaN
const ratio = (n: number | null | undefined): number | null => typeof n === 'number' && Number.isFinite(n) && n >= 0 && n <= 1 ? n : null
const activeAt = (r: Revision, t: number) => time(r.effectiveFrom) <= t && (!r.effectiveUntil || time(r.effectiveUntil) > t)
/** Latest known revision first, then valid-time filter: a deletion must not resurrect an old row. */
export function revisionsAt<T extends Revision>(rows: T[], known: number, errors: string[]): T[] {
  const grouped = new Map<string, T[]>()
  for (const r of rows) {
    if (Number.isFinite(time(r.recordedAt)) && time(r.recordedAt) > known) continue
    if (!r.id || !Number.isFinite(time(r.recordedAt)) || !Number.isFinite(time(r.effectiveFrom)) || (r.effectiveUntil != null && (!Number.isFinite(time(r.effectiveUntil)) || time(r.effectiveUntil) <= time(r.effectiveFrom)))) { errors.push('INVALID_REVISION'); continue }
    if (time(r.recordedAt) > known) continue
    grouped.set(r.id, [...(grouped.get(r.id) ?? []), r])
  }
  return [...grouped.entries()].sort(([a],[b]) => a.localeCompare(b)).flatMap(([id, items]) => {
    const latest = Math.max(...items.map(r => time(r.recordedAt)))
    const top = items.filter(r => time(r.recordedAt) === latest)
    if (new Set(top.map(r => stable(r))).size > 1) { errors.push(`CONFLICTING_REVISION:${id}`); return [] }
    return [top[0]!]
  })
}
function stable(v: unknown): string {
  if (Array.isArray(v)) return '[' + v.map(stable).join(',') + ']'
  if (v && typeof v === 'object') return '{' + Object.entries(v).sort(([a],[b])=>a.localeCompare(b)).map(([k,x])=>JSON.stringify(k)+':'+stable(x)).join(',') + '}'
  return JSON.stringify(v) ?? 'null'
}
export function evaluateDyadAdmissibility(i: {
  coldStart: boolean; evidenceCount: number; reliability: number | null; coverage: number | null
  identity: IdentityQuality; completeness: Completeness; status: string; roleKnown: boolean; allAxesObserved?: boolean; errors: string[]
}) {
  const reasons = [...i.errors]
  if (i.coldStart) reasons.push('COLD_START')
  if (i.evidenceCount < RELIABILITY_PARAMS_V1.p7MarkersMin) reasons.push('INSUFFICIENT_INDEPENDENT_EVIDENCE')
  if (i.identity !== 'verified') reasons.push('IDENTITY_NOT_VERIFIED')
  if (i.completeness !== 'complete') reasons.push('INCOMPLETE_DATA')
  if (!i.roleKnown) reasons.push('UNKNOWN_ROLE')
  if (ratio(i.coverage) == null || i.coverage === 0) reasons.push('UNKNOWN_OR_ZERO_COVERAGE')
  if (ratio(i.reliability) == null || i.reliability! < RELIABILITY_PARAMS_V1.thresholds.amber) reasons.push('INSUFFICIENT_RELIABILITY')
  if (i.allAxesObserved === false) reasons.push('UNOBSERVED_AXES')
  const display = reasons.length === 0
  const verdict = display && i.reliability! >= RELIABILITY_PARAMS_V1.thresholds.verdict
  return { display, verdict, account: verdict && ['actif','ralenti'].includes(i.status), recommendation: verdict,
    trend: verdict, reasons: [...new Set(reasons)].sort() }
}
export interface RelationalState {
  entity: DyadIdentity; scope: 'individual_dyad'; status: string; observedAt: string; computedAt: string; knowledgeAt: string; replayMode: ReplayMode
  score: number | null; exploratoryScore: number | null; axes: Partial<Record<AxisId, number | null>>
  reliability: number | null; coverage: { value: number | null; completeness: Completeness; expectedChannels: string[] | null; observedChannels: string[] }
  authority: number | null; declaredRole: DyadRole | null; inferredRole: DyadRole | null
  admissibility: ReturnType<typeof evaluateDyadAdmissibility>; evidence: RelationalEvent[]; contributions: Array<MarkerContribution & { axis: AxisId }>
  history: Array<{ at: string; score: number | null }>; delta: number | null; causes: Array<{ kind: 'calculated'; cause: string; points: number }>
  scoringVersion: string; paramsVersion: string; registryVersion: string; errors: string[]
}
export function buildRelationalState(input: FoundationInput): RelationalState {
  const key = dyadKey(input.dyad), t = time(input.at)
  const mode = input.mode ?? 'state_as_known_at_T'
  const knowledgeAt = mode === 'state_as_known_at_T' ? input.at : input.knowledgeAt
  if (!Number.isFinite(t) || !knowledgeAt || !Number.isFinite(time(knowledgeAt)) || !Number.isFinite(time(input.computedAt))) throw new Error('INVALID_REPLAY_TIME')
  const known = time(knowledgeAt), errors: string[] = []
  const matches = (d: DyadIdentity) => dyadKey(d) === key
  const events = revisionsAt(input.events.filter(e => matches(e.dyad)), known, errors).filter(e =>
    activeAt(e,t) && e.state === 'observed' && time(e.eventTime) <= t && time(e.ingestedAt) <= known &&
    e.identityQuality === 'verified' && e.completeness === 'complete' && e.participationObserved &&
    !!e.evidenceRef && !!e.evidenceUnitId && !!e.sourceVersion &&
    (e.internalActorId === input.dyad.collaboratorUserId || e.ownerUserId === input.dyad.collaboratorUserId) &&
    (e.externalActorId === input.dyad.contactId || e.participants.includes(input.dyad.contactId)))
  const byId = new Map(events.map(e => [e.id,e]))
  const markers = revisionsAt(input.markers.filter(e => matches(e.dyad)),known,errors)
  const consumedUnits = new Map<string, Set<string>>()
  const admitted: MarkerEvent[] = [], usedEvents = new Map<string, RelationalEvent>()
  for (const m of markers) {
    if (time(m.observedAt)>t || time(m.effectiveFrom)>t) continue
    const entry = input.registry.markers[m.markerId]
    if (!entry || entry.scope !== 'person' || !entry.axis || entry.deprecatedAt) { errors.push(`UNKNOWN_OR_INVALID_MARKER:${m.markerId}`); continue }
    if (m.registryVersion !== input.registry.version) { errors.push(`REGISTRY_MISMATCH:${m.id}`); continue }
    if (!activeAt(m,t) || m.state !== 'active' || m.status !== 'accepted' || time(m.observedAt) > t || !Number.isFinite(time(m.observedAt)) || (m.resolvedAt && time(m.resolvedAt) <= t) || (m.supersededAt && time(m.supersededAt) <= t)) continue
    if (![1,-1].includes(m.sense)) { errors.push(`INVALID_SENSE:${m.id}`); continue }
    const support = m.sourceEventIds.map(id => byId.get(id))
    if (!support.length || support.some(e=>!e)) { errors.push(`INADMISSIBLE_EVIDENCE:${m.id}`); continue }
    if (entry.tier==='critique' && (m.criticalValidated!==true || !m.evidenceQuote?.trim() || !support.some(e=>e!.evidenceText?.includes(m.evidenceQuote!)))) { errors.push(`UNVALIDATED_CRITICAL_EVIDENCE:${m.id}`); continue }
    if (support.some(e=>time(e!.eventTime)>time(m.observedAt))) { errors.push(`EVIDENCE_AFTER_OBSERVATION:${m.id}`); continue }
    const units = [...new Set(support.map(e=>e!.evidenceUnitId))].sort()
    const family = `${m.markerId}:${m.sense}`
    const seen = consumedUnits.get(family) ?? new Set<string>()
    if (units.some(u=>seen.has(u))) continue // overlapping interpretations are not independent repetitions
    units.forEach(u=>seen.add(u)); consumedUnits.set(family,seen)
    // A compound measurement is one occurrence, never N repetitions.
    admitted.push({markerId:m.markerId,sense:m.sense,observedAt:m.observedAt,evidenceUnitId:JSON.stringify(units),evidenceRef:m.id})
    for (const e of support) usedEvents.set(e!.id,e!)
  }
  // Connected support sets count once for P7: an aggregate cadence marker
  // supported by 100 emails is one observation, not 100 independent markers.
  const components: Set<string>[] = []
  for (const marker of admitted) {
    const group = new Set<string>(JSON.parse(marker.evidenceUnitId!))
    for (let i=components.length-1;i>=0;i--) {
      if ([...components[i]!].some(unit=>group.has(unit))) {
        components[i]!.forEach(unit=>group.add(unit)); components.splice(i,1)
      }
    }
    components.push(group)
  }
  const choose = <T extends Revision>(rows:T[]): T | undefined => {
    const active = revisionsAt(rows,known,errors).filter(r=>activeAt(r,t)).sort((a,b)=>time(b.effectiveFrom)-time(a.effectiveFrom)||time(b.recordedAt)-time(a.recordedAt)||a.id.localeCompare(b.id))
    if (active.length>1 && time(active[0]!.effectiveFrom)===time(active[1]!.effectiveFrom) && time(active[0]!.recordedAt)===time(active[1]!.recordedAt)) {
      errors.push('AMBIGUOUS_TEMPORAL_CONTEXT'); return undefined
    }
    return active[0]
  }
  const quality = choose(input.qualities)
  const declared = choose(input.roles.filter(r=>r.origin==='declared'))
  const inferred = choose(input.roles.filter(r=>r.origin==='inferred'))
  const role = declared?.role ?? null // inference is kept, not silently promoted
  const datesByUnit = new Map<string,number>()
  for (const e of events) {
    if (datesByUnit.has(e.evidenceUnitId) && datesByUnit.get(e.evidenceUnitId)!==time(e.eventTime)) errors.push(`CONFLICTING_EVENT_TIME:${e.evidenceUnitId}`)
    datesByUnit.set(e.evidenceUnitId,Math.min(datesByUnit.get(e.evidenceUnitId) ?? Infinity,time(e.eventTime)))
  }
  const eventTimes = [...datesByUnit.values()].sort((a,b)=>a-b)
  const gaps = eventTimes.slice(1).map((n,i)=>(n-eventTimes[i]!)/86400000).sort((a,b)=>a-b)
  const cadence = gaps.length ? (gaps[Math.floor((gaps.length-1)/2)]! + gaps[Math.floor(gaps.length/2)]!)/2 : 0
  const coldStart = eventTimes.length < 5 || (t-(eventTimes[0] ?? t))/86400000 < 30
  const status = !admitted.length ? 'insufficient_evidence' : coldStart ? 'cold_start' : statusFromCadence((t-eventTimes.at(-1)!)/86400000,cadence,false)
  const expected = quality?.expectedChannels ? [...new Set(quality.expectedChannels)].sort() : null
  const observed = [...new Set(events.filter(e=>quality?.periodStart && quality.periodEnd && time(e.eventTime)>=time(quality.periodStart) && time(e.eventTime)<=time(quality.periodEnd)).map(e=>e.channel))].sort()
  const coverage = expected?.length && quality?.periodStart && quality.periodEnd && time(quality.periodStart) <= time(quality.periodEnd) && time(quality.periodEnd) <= t
    ? expected.filter(c=>observed.includes(c)).length/expected.length : null
  const reliability = quality?.reliabilityEvidence.length && quality.identity === 'verified' && quality.diarization === 'verified' ? ratio(quality.reliability) : null
  const core = admitted.length && role && !coldStart ? calculateDyadScoreCore(admitted,role,input.params,input.registry) : null
  const allAxesObserved = !!core && Object.values(core.axes).every(a=>a.contributions.length > 0)
  const admissibility = evaluateDyadAdmissibility({coldStart,allAxesObserved,evidenceCount:components.length,reliability,coverage,identity:quality?.identity ?? 'unknown',completeness:quality?.completeness ?? 'unknown',status,roleKnown:!!role,errors})
  const axes = core ? Object.fromEntries(Object.values(core.axes).map(a=>[a.axis,a.contributions.length ? a.value : null])) : {}
  return {entity:input.dyad,scope:'individual_dyad',status,score:admissibility.display ? core!.score : null,exploratoryScore:core?.score ?? null,axes,
    reliability,coverage:{value:coverage,completeness:quality?.completeness ?? 'unknown',expectedChannels:expected,observedChannels:observed},
    authority:declared?.authority != null && declared.authority > 0 ? declared.authority : null,declaredRole:role,inferredRole:inferred?.role ?? null,
    admissibility,evidence:[...usedEvents.values()].sort((a,b)=>a.id.localeCompare(b.id)),contributions:core ? Object.values(core.axes).flatMap(a=>a.contributions.map(c=>({...c,axis:a.axis}))) : [],
    observedAt:input.at,computedAt:input.computedAt,knowledgeAt,replayMode:mode,history:[],delta:null,causes:[],scoringVersion:SCORING_VERSION,paramsVersion:input.params.version,registryVersion:input.registry.version,errors:[...new Set(errors)].sort()}
}
/** Prepared account boundary: no guessed team-person aggregation or authority. */
export function eligibleAccountDyads(states: RelationalState[]) {
  return states.filter(s=>s.admissibility.account && s.authority !== null && s.score !== null)
}
export type CommitmentOutcome = 'open'|'held_on_time'|'held_late'|'cancelled'|'waived'|'broken'|'unknown'
export function commitmentOutcome(c: {dueAt?:string|null;completedAt?:string|null;resolvedAt?:string|null;disposition?:'cancelled'|'waived'|'broken'|null},at:string): CommitmentOutcome {
  if ([c.dueAt,c.completedAt,c.resolvedAt].some(v=>v != null && !Number.isFinite(time(v))) || !Number.isFinite(time(at))) return 'unknown'
  if (c.disposition) return c.disposition
  if (c.completedAt && time(c.completedAt)<=time(at)) return c.dueAt ? time(c.completedAt)<=time(c.dueAt) ? 'held_on_time':'held_late' : 'unknown'
  if (c.resolvedAt && time(c.resolvedAt)<=time(at)) return 'unknown'
  return 'open' // overdue does not prove broken; no 90-day exclusion
}
"},{"name":"functions/_shared/scoring-v6/calculateDyadScoreCore.ts","content":"// Canonical V6 module: shared by browser and edge.
// Scoring V6 — NOYAU personne. Fonction PURE : mêmes entrées → mêmes sorties.
// Aucune DB, aucun LLM, aucune fenêtre temporelle, aucune fiabilité, aucun P4/P5/P7.
// Ces règles obligatoires vivent dans buildDyadScoreSnapshot() (couche ultérieure).
// Voir SCORING_V6_S0_DESIGN.md §F et SCORING_DOCTRINE.md.

import type {
  AxisId, DyadRole, DyadScoreCoreResult, MarkerContribution, MarkerEvent,
  MarkerRegistry, MarkerRegistryEntry, ScoringParams,
} from './types.ts'

const AXES: AxisId[] = ['confiance', 'satisfaction', 'engagement', 'reciprocite', 'ancrage']
const clamp = (v: number, min: number, max: number) => Math.max(min, Math.min(max, v))
const signOf = (v: number): -1 | 0 | 1 => (v > 0 ? 1 : v < 0 ? -1 : 0)

/** Points signés d'un marqueur selon le mode. PALIER : le palier décide (ptsSpec
 *  ignoré). SPEC : ptsSpec (signé pour fixe-signe, |ptsSpec|×sens pour bipolaire). */
function effectivePoints(entry: MarkerRegistryEntry, sense: -1 | 1, params: ScoringParams): number {
  const effSign: -1 | 1 = entry.sign !== 0 ? entry.sign : sense
  if (params.mode === 'spec') {
    const spec = entry.ptsSpec ?? 0
    return entry.sign !== 0 ? spec : Math.abs(spec) * effSign
  }
  const tier = params.tiers[entry.tier]
  return effSign > 0 ? tier.pos : tier.neg
}

/** Renormalisation de la volontarité par rôle (exception Exécution du registre V6). */
function renormVolontarite(volBase: number, role: DyadRole, params: ScoringParams): number {
  const table = role.volontariteProfile === 'execution' ? params.volontarite.execution : params.volontarite
  if (volBase === 0.3) return table.prescrit
  if (volBase === 0.6) return table.semi
  if (volBase === 1.0) return table.volontaire
  return volBase // valeur hors barème : renvoyée telle quelle (jamais fabriquée)
}

function repetitionMultiplier(occurrences: number, params: ScoringParams): number {
  if (occurrences >= 4) return params.repetition.occ4plus
  if (occurrences >= 2) return params.repetition.occ2to3
  return params.repetition.occ1
}

/**
 * Calcule les 5 axes C/S/E/R/A d'une dyade à partir de marker_events déjà
 * admissibles. `params` et `registry` sont des objets RÉSOLUS (le core ne
 * résout jamais une version depuis une DB) ; leurs versions sont rapportées
 * dans le résultat pour la reproductibilité.
 */
export function calculateDyadScoreCore(
  markerEvents: MarkerEvent[],
  role: DyadRole,
  params: ScoringParams,
  registry: MarkerRegistry,
): DyadScoreCoreResult {
  const axes = {} as DyadScoreCoreResult['axes']

  for (const axis of AXES) {
    // Ne retenir que les events dont le marqueur existe, appartient à CET axe,
    // et n'est pas déprécié. Un marker_id inconnu du registre est ignoré (jamais
    // scoré) — le rejet dur se fait à l'insertion du marker_event, pas ici.
    const axisEvents = markerEvents.filter((event) => {
      const entry = registry.markers[event.markerId]
      return entry && !entry.deprecatedAt && entry.axis === axis
    })

    if (axisEvents.length === 0) {
      // Axe observé sans marqueur → base 50 (le null « hors fenêtre » est décidé
      // par la couche snapshot, jamais ici).
      axes[axis] = { axis, base: 50, value: 50, weight: params.axisWeights[axis], cappedByS07: false, contributions: [] }
      continue
    }

    // Regroupement par (marker_id, sens effectif). Fixe-signe : sens = entry.sign,
    // donc une seule clé par marqueur. Bipolaire : +1 et -1 sont deux groupes.
    const groups = new Map<string, { entry: MarkerRegistryEntry; sense: -1 | 1; units: Set<string>; refs: Set<string> }>()
    for (const event of axisEvents) {
      const entry = registry.markers[event.markerId]!
      const sense: -1 | 1 = entry.sign !== 0 ? (entry.sign as -1 | 1) : event.sense
      const key = `${event.markerId}|${sense}`
      const g = groups.get(key)
      const unit = event.evidenceUnitId ?? event.evidenceRef
      if (g) { g.units.add(unit); g.refs.add(event.evidenceRef) }
      else groups.set(key, { entry, sense, units: new Set([unit]), refs: new Set([event.evidenceRef]) })
    }

    // Contributions (avant décroissance)
    const raw: Array<Omit<MarkerContribution, 'rank' | 'decayMultiplier' | 'contributionFinale'>> = []
    for (const { entry, sense, units, refs } of groups.values()) {
      const count = units.size
      const pts = effectivePoints(entry, sense, params)
      const vol = renormVolontarite(entry.volBase, role, params)
      const rep = repetitionMultiplier(count, params)
      const magnitude = Math.abs(pts) * vol * rep
      raw.push({ markerId: entry.markerId, sense, occurrences: count, evidenceUnitIds: [...units].sort(), evidenceRefs: [...refs].sort(), pointsEffectifs: pts, volontarite: vol, repetitionMultiplier: rep, magnitude })
    }

    // Equal magnitudes share the arithmetic mean of occupied rank coefficients.
    // This preserves total rank mass, without preferring either sign. Sorting
    // below only canonicalizes the serialized explanation, not the weighting.
    raw.sort((a, b) => (b.magnitude - a.magnitude) || a.markerId.localeCompare(b.markerId) || a.sense - b.sense)
    const coefficient = (i: number) => params.decay[Math.min(i, params.decay.length - 1)] ?? 1
    const contributions: MarkerContribution[] = raw.map((c, index) => {
      const first = raw.findIndex(x => x.magnitude === c.magnitude)
      let end = first
      while (end < raw.length && raw[end]!.magnitude === c.magnitude) end++
      let mass = 0
      for (let i = first; i < end; i++) mass += coefficient(i)
      const decayMultiplier = mass / (end - first)
      return { ...c, rank: first + 1, decayMultiplier,
        contributionFinale: signOf(c.pointsEffectifs) * c.magnitude * decayMultiplier }
    })

    const total = contributions.reduce((sum, c) => sum + c.contributionFinale, 0)
    let value = clamp(Math.round(50 + total), 0, 100)

    // Plafond critique S07 : Satisfaction ≤ 20, appliqué APRÈS le calcul normal.
    const cappedByS07 = axis === 'satisfaction' && axisEvents.some((e) => e.markerId === 'S07')
    if (cappedByS07) value = Math.min(value, 20)

    axes[axis] = { axis, base: 50, value, weight: params.axisWeights[axis], cappedByS07, contributions }
  }

  // Score final = Σ (valeur d'axe ARRONDIE × poids), puis arrondi (reproduit l'exemple V6).
  const score = Math.round(AXES.reduce((sum, axis) => sum + axes[axis].value * axes[axis].weight, 0))

  return {
    score,
    axes,
    role,
    paramsVersion: params.version,
    registryVersion: registry.version,
    mode: params.mode,
  }
}
"},{"name":"functions/_shared/scoring-v6/snapshots.ts","content":"// Canonical V6 module: shared by browser and edge.
// Scoring V6 — S6 : couche SNAPSHOT (applique ce que le noyau mathématique ignore).
// Fenêtre d'extraction, P5 (cold start), P7 (verdict), fiabilité, statut cadence.
// Pur (aucune DB/LLM). Les coefficients de fiabilité sont PROVISIONAL et versionnés
// (jamais inventés silencieusement — §28). Voir SCORING_DOCTRINE.md / SCORING_V6_S0_DESIGN.md.

import { calculateDyadScoreCore } from './calculateDyadScoreCore.ts'
import type {
  AccountWeatherCoreResult, DyadRole, DyadScoreCoreResult, MarkerEvent, MarkerRegistry, ScoringParams,
} from './types.ts'

/** Paramètres de fiabilité — provisional, versionnés (§28). */
export const RELIABILITY_PARAMS_V1 = {
  version: 'reliability_params-v1',
  status: 'provisional' as const,
  volumeSaturationMarkers: 8,   // nb de marqueurs au-delà duquel le facteur volume = 1
  x01Cap: 0.6,                  // canal non instrumenté (X01) → plafond de fiabilité
  significantDialWeight: 0.15,  // cadran « significatif » pour le min compte
  thresholds: { verdict: 0.60, amber: 0.50 },
  // P5 / P7
  p5AgeMinDays: 30, p5EpisodesMin: 5, p7MarkersMin: 5,
  // Statut cadence
  cadence: { actif: 1.5, ralenti: 3, rompu: 6 },
}

const clamp01 = (x: number) => Math.max(0, Math.min(1, Number.isFinite(x) ? x : 0))

export type RelationalStatus = 'actif' | 'ralenti' | 'dormant' | 'rompu' | 'cold_start' | 'insufficient_evidence'

/** Statut = cadence PROPRE de la dyade, jamais un seuil absolu (§29). */
export function statusFromCadence(daysSinceLast: number, cadenceMedian: number, hasX02: boolean): RelationalStatus {
  if (hasX02) return 'rompu'
  if (cadenceMedian <= 0) return 'actif'
  const ratio = daysSinceLast / cadenceMedian
  const c = RELIABILITY_PARAMS_V1.cadence
  if (ratio > c.rompu) return 'rompu'
  if (ratio > c.ralenti) return 'dormant'
  if (ratio >= c.actif) return 'ralenti'
  return 'actif'
}

export interface DyadReliabilityInputs {
  channelCoverage: number      // 0-1 : part des canaux plausibles réellement captés
  identityResolution: number   // 0-1 : 1 = identité nette ; boîte partagée non scindée → ≤ 0.60 (P3)
  diarizationQuality: number   // 0-1
  markerCount: number
  hasX01: boolean
}

/** Fiabilité dyade = couverture_canal × volume × identité × diarisation (§28), tous 0-1.
 *  X01 (canal non instrumenté) plafonne. Provisional. */
export function reliabilityDyad(r: DyadReliabilityInputs): number {
  const volume = clamp01(r.markerCount / RELIABILITY_PARAMS_V1.volumeSaturationMarkers)
  let rel = clamp01(r.channelCoverage) * volume * clamp01(r.identityResolution) * clamp01(r.diarizationQuality)
  if (r.hasX01) rel = Math.min(rel, RELIABILITY_PARAMS_V1.x01Cap)
  return clamp01(rel)
}

export interface DyadSnapshotInput {
  markerEvents: MarkerEvent[]
  role: DyadRole
  at: string                   // date de rejeu T
  context: { ageDays: number; episodes: number; daysSinceLast: number; cadenceMedian: number; hasX02: boolean }
  reliabilityInputs: Omit<DyadReliabilityInputs, 'markerCount'>
  params: ScoringParams
  registry: MarkerRegistry
}

export interface DyadSnapshot {
  entityType: 'dyad'
  at: string
  score: number | null         // null si P5 (cold start)
  reliability: number
  verdictAllowed: boolean       // P7 : ≥5 marqueurs datés
  status: RelationalStatus
  coldStart: boolean
  markerCount: number
  core: DyadScoreCoreResult | null
  paramsVersion: string
  registryVersion: string
  reliabilityParamsVersion: string
}

/** Applique fenêtre + P5 + P7 + fiabilité + statut au noyau mathématique. */
export function buildDyadScoreSnapshot(input: DyadSnapshotInput): DyadSnapshot {
  const { at, params, registry } = input
  const atMs = new Date(at).getTime()
  // Fenêtre temporelle : seuls les marqueurs observés ≤ T (rejeu daté).
  const windowed = input.markerEvents.filter((e) => Number.isFinite(new Date(e.observedAt).getTime()) && new Date(e.observedAt).getTime() <= atMs && !!e.evidenceRef?.trim() && !!registry.markers[e.markerId]?.axis && !registry.markers[e.markerId]?.deprecatedAt && (e.sense === 1 || e.sense === -1))
  const markerCount = new Set(windowed.map(e => e.evidenceUnitId ?? e.evidenceRef)).size

  const reliability = reliabilityDyad({ ...input.reliabilityInputs, markerCount })
  const p5 = input.context.ageDays < RELIABILITY_PARAMS_V1.p5AgeMinDays || input.context.episodes < RELIABILITY_PARAMS_V1.p5EpisodesMin
  const status = p5 ? 'cold_start' : statusFromCadence(input.context.daysSinceLast, input.context.cadenceMedian, input.context.hasX02)

  if (p5 || markerCount === 0) {
    return {
      entityType: 'dyad', at, score: null, reliability, verdictAllowed: false, status: p5 ? status : 'insufficient_evidence', coldStart: p5,
      markerCount, core: null, paramsVersion: params.version, registryVersion: registry.version,
      reliabilityParamsVersion: RELIABILITY_PARAMS_V1.version,
    }
  }

  const core = calculateDyadScoreCore(windowed, input.role, params, registry)
  return {
    entityType: 'dyad', at, score: core.score, reliability,
    verdictAllowed: markerCount >= RELIABILITY_PARAMS_V1.p7MarkersMin, // P7
    status, coldStart: false, markerCount, core,
    paramsVersion: params.version, registryVersion: registry.version,
    reliabilityParamsVersion: RELIABILITY_PARAMS_V1.version,
  }
}

export interface AccountSnapshotInput {
  weather: AccountWeatherCoreResult
  at: string
  dialReliabilities: Partial<Record<string, number>>  // par dial (0-1)
  activeDyadCount: number
}
export interface AccountSnapshot {
  entityType: 'account'
  at: string
  score: number | null
  reliability: number
  verdictAllowed: boolean
  weakestDial: string | null
  paramsVersion: string
  registryVersion: string
  reliabilityParamsVersion: string
}

/** Fiabilité compte = min des fiabilités des cadrans significatifs (poids ≥ 15%) — §28. */
export function buildAccountWeatherSnapshot(input: AccountSnapshotInput): AccountSnapshot {
  const { weather } = input
  const significant = Object.values(weather.dials)
    .filter((d) => d.value !== null && d.weight >= RELIABILITY_PARAMS_V1.significantDialWeight)
    .map((d) => clamp01(input.dialReliabilities[d.dial] ?? 0))
  const reliability = significant.length ? Math.min(...significant) : 0
  // Verdict compte : au moins une dyade active et un score calculable.
  const verdictAllowed = input.activeDyadCount >= 1 && weather.score !== null
  return {
    entityType: 'account', at: input.at, score: weather.score, reliability, verdictAllowed,
    weakestDial: weather.weakestDial, paramsVersion: weather.paramsVersion,
    registryVersion: weather.registryVersion, reliabilityParamsVersion: RELIABILITY_PARAMS_V1.version,
  }
}

/** Règle d'affichage UI dérivée de la fiabilité (§28/§50) — décision déterministe, jamais un LLM. */
export function displayRule(reliability: number | null, verdictAllowed: boolean): 'score_and_verdict' | 'score_amber' | 'score_greyed_no_verdict' {
  if (reliability == null || !Number.isFinite(reliability) || reliability < RELIABILITY_PARAMS_V1.thresholds.amber) return 'score_greyed_no_verdict'
  if (!verdictAllowed) return 'score_greyed_no_verdict' // P7 : score possible, aucun verdict
  if (reliability < RELIABILITY_PARAMS_V1.thresholds.verdict) return 'score_amber'
  return 'score_and_verdict'
}
"},{"name":"functions/_shared/scoring-v6/pipeline.ts","content":"import { buildRelationalState, dyadKey, revisionsAt, type FoundationInput, type RelationalEvent, type MarkerRevision } from './foundation.ts'
import { runDeterministicDetectors } from './detectors.ts'
export function detectNormalizedEvents(events: RelationalEvent[], dyad: FoundationInput['dyad'], at: string): {markers:MarkerRevision[];errors:string[]} {
  const errors:string[]=[], now=Date.parse(at), key=dyadKey(dyad)
  const available=revisionsAt(events.filter(e=>dyadKey(e.dyad)===key),now,errors).filter(e=>
    e.state==='observed' && e.identityQuality==='verified' && e.completeness==='complete' && e.participationObserved &&
    Date.parse(e.eventTime)<=now && Date.parse(e.ingestedAt)<=now && Date.parse(e.effectiveFrom)<=now && (!e.effectiveUntil || Date.parse(e.effectiveUntil)>now))
  const messages=available.filter(e=>e.direction && e.threadId).map(e=>({id:e.id,threadId:e.threadId!,sentAt:e.eventTime,direction:e.direction!}))
  const meetings=available.filter(e=>e.channel==='meeting').map(e=>({id:e.id,startsAt:e.eventTime,occurred:true,contactParticipated:true,state:'observed' as const}))
  const {drafts}=runDeterministicDetectors(messages,meetings,now)
  return {errors,markers:drafts.map(d=>{
    // A statistical observation references every event in its measurement input.
    // Never use 'channels' or 'continuity' as an evidence identity.
    const supports=(d.markerId==='S04' ? available.filter(e=>e.threadId===d.measure.threadId) : available).filter(e=>Date.parse(e.eventTime)<=Date.parse(d.observedAt)).map(e=>e.id).sort()
    return {id:`det:${d.markerId}:${d.sense}:${d.evidenceRef}`,dyad,recordedAt:at,effectiveFrom:at,markerId:d.markerId,sense:d.sense,observedAt:d.observedAt,
      sourceEventIds:supports,state:'active',status:d.status==='accepted'?'accepted':'candidate',registryVersion:'reg-v6.0',detectorVersion:'normalized-detectors-v2',voluntariness:'unknown',intensity:'unknown'}
  })}
}
export async function checked<T=any>(q:PromiseLike<{data:T;error:any}>):Promise<T> { const r=await q;if(r.error) throw new Error(r.error.message ?? String(r.error));return r.data }
export async function allRows(db:any,table:string,select:string,scope:(q:any)=>any) {
  const rows:any[]=[]
  for(let offset=0;;offset+=500){const batch=await checked<any[]>(scope(db.from(table).select(select)).order('id').range(offset,offset+499)); rows.push(...batch); if(batch.length<500)return rows}
}
export async function listDyads(db:any,after:string|null) { return checked<any[]>(db.rpc('v6_foundation_list',{p_after:after,p_limit:25})) }
export async function loadLedger(db:any,id:string) { return checked(db.rpc('v6_foundation_read',{p_dyad_id:id})) }
export async function scoreLedger(db:any,row:any,at:string,params:FoundationInput['params'],registry:FoundationInput['registry']) {
  const ledger=await loadLedger(db,row.id)
  const state=buildRelationalState({...ledger,dyad:{organizationId:row.organization_id,collaboratorUserId:row.collaborator_user_id,contactId:row.contact_id},at,computedAt:at,params,registry})
  await checked(db.rpc('v6_foundation_store',{p_dyad_id:row.id,p_kind:'snapshot',p_payload:state}))
  return state
}
"},{"name":"functions/_shared/scoring-v6/detectors.ts","content":"// Canonical V6 module: shared by browser and edge.
// Détecteurs DÉTERMINISTES V6 — purs, sans DB/LLM. Produisent des marker_event
// « drafts » (preuve + date obligatoires) à partir des données RÉELLES disponibles
// (communication_messages, meetings). Un draft n'entre PAS dans le score tant qu'il
// n'est pas persisté ; un draft `candidate` n'entre jamais tel quel (validation requise).
//
// Disponibilité auditée le 2026-09-14 :
//   • messages : thread_id, direction, sent_at, subject → OK (latence, cadence, threads)
//   • meetings + meeting_participants → OK (présence), MAIS response_status = 'needsAction'
//     uniquement → pas d'accept/decline → E05 = candidate_only
//   • cc réel non capté (metadata: from/to seulement) → C02 blocked_by_missing_source
//   • corps non stocké (analyzed_without_body_storage) → C03/S01 (formalité/hedging) blocked
// Voir FINAL_ACCOUNT_ENGINE_V6_REPORT.md §6.

export const DETECTOR_VERSION = 'detectors-v1'

export interface DyadMessage {
  id: string
  threadId: string
  direction: 'inbound' | 'outbound' // inbound = du contact vers nous
  sentAt: string
  subject?: string | null
}
export interface DyadMeeting {
  id: string
  startsAt: string
  state?: 'observed' | 'scheduled' | 'cancelled' | 'corrected' | 'deleted'
  occurred: boolean            // réunion réellement tenue (passée / brief)
  contactParticipated: boolean
}

export interface MarkerEventDraft {
  markerId: string
  scope: 'person'
  sense: -1 | 1
  observedAt: string
  evidenceRef: string          // id d'un message/réunion représentatif
  evidenceText: string
  measure: Record<string, unknown>
  detectorVersion: string
  confidence: number           // 0-1
  status: 'accepted' | 'candidate'  // candidate = ne pas scorer tant que non validé
}

const DAY = 86_400_000
const median = (xs: number[]): number | null => {
  if (!xs.length) return null
  const s = [...xs].sort((a, b) => a - b)
  const mid = Math.floor(s.length / 2)
  return s.length % 2 ? s[mid]! : (s[mid - 1]! + s[mid]!) / 2
}

// ── P4 : baseline dyade (fenêtre glissante, défaut 182 j ≈ 6 mois) ───────────
export interface DyadBaseline {
  episodes: number
  sufficient: boolean          // ≥ 8 épisodes → marqueurs de déviation autorisés
  reliabilityCap: number       // ≤ 0.50 sous 8 épisodes (P4)
  cadenceMedianDays: number | null
  contactResponseMedianHours: number | null // latence : notre outbound → leur inbound
  ourResponseMedianHours: number | null      // leur inbound → notre outbound
  avgThreadDepth: number | null
  channels: string[]
  windowDays: number
}

export function computeDyadBaseline(messages: DyadMessage[], meetings: DyadMeeting[], nowMs: number, windowDays = 182): DyadBaseline {
  const from = nowMs - windowDays * DAY
  const msg = messages.filter((m) => { const t = new Date(m.sentAt).getTime(); return t >= from && t <= nowMs }).sort((a, b) => new Date(a.sentAt).getTime() - new Date(b.sentAt).getTime())
  const meet = meetings.filter((m) => m.occurred && m.contactParticipated && (!m.state || m.state === 'observed')).filter((m) => { const t = new Date(m.startsAt).getTime(); return t >= from && t <= nowMs })
  const episodes = msg.length + meet.length

  // Latences par sens, à l'intérieur de chaque thread (messages consécutifs de sens opposé).
  const byThread = new Map<string, DyadMessage[]>()
  for (const m of msg) byThread.set(m.threadId, [...(byThread.get(m.threadId) ?? []), m])
  const contactResp: number[] = []
  const ourResp: number[] = []
  for (const arr of byThread.values()) {
    const s = arr.sort((a, b) => new Date(a.sentAt).getTime() - new Date(b.sentAt).getTime())
    for (let i = 1; i < s.length; i++) {
      const prev = s[i - 1]!, cur = s[i]!
      if (prev.direction === cur.direction) continue
      const gapH = (new Date(cur.sentAt).getTime() - new Date(prev.sentAt).getTime()) / 3_600_000
      if (prev.direction === 'outbound' && cur.direction === 'inbound') contactResp.push(gapH)
      else if (prev.direction === 'inbound' && cur.direction === 'outbound') ourResp.push(gapH)
    }
  }

  // Cadence : médiane des écarts entre interactions consécutives (tous types).
  const times = [...msg.map((m) => new Date(m.sentAt).getTime()), ...meet.map((m) => new Date(m.startsAt).getTime())].sort((a, b) => a - b)
  const gaps: number[] = []
  for (let i = 1; i < times.length; i++) gaps.push((times[i]! - times[i - 1]!) / DAY)

  const channels: string[] = []
  if (msg.length) channels.push('email')
  if (meet.length) channels.push('meeting')

  const sufficient = episodes >= 8
  return {
    episodes, sufficient, reliabilityCap: sufficient ? 1 : 0.5,
    cadenceMedianDays: median(gaps),
    contactResponseMedianHours: median(contactResp),
    ourResponseMedianHours: median(ourResp),
    avgThreadDepth: byThread.size ? msg.length / byThread.size : null,
    channels, windowDays,
  }
}

// ── S04 : même demande relancée ≥ 2× sans réponse (déterministe) ─────────────
// Un thread avec ≥ 2 outbound sur des jours distincts et 0 inbound = relances sans réponse.
export function detectS04(messages: DyadMessage[]): MarkerEventDraft[] {
  const byThread = new Map<string, DyadMessage[]>()
  for (const m of messages) byThread.set(m.threadId, [...(byThread.get(m.threadId) ?? []), m])
  const out: MarkerEventDraft[] = []
  for (const [threadId, arr] of byThread) {
    const outbound = arr.filter((m) => m.direction === 'outbound')
    const inbound = arr.filter((m) => m.direction === 'inbound')
    if (inbound.length > 0 || outbound.length < 2) continue
    const days = new Set(outbound.map((m) => m.sentAt.slice(0, 10)))
    if (days.size < 2) continue // relances le même jour = pas une vraie relance espacée
    const sorted = outbound.sort((a, b) => new Date(a.sentAt).getTime() - new Date(b.sentAt).getTime())
    const spanDays = (new Date(sorted[sorted.length - 1]!.sentAt).getTime() - new Date(sorted[0]!.sentAt).getTime()) / DAY
    out.push({
      markerId: 'S04', scope: 'person', sense: -1, observedAt: sorted[sorted.length - 1]!.sentAt,
      evidenceRef: sorted[0]!.id,
      evidenceText: `${outbound.length} relances sans réponse sur « ${sorted[0]!.subject ?? 'sujet inconnu'} » (${Math.round(spanDays)} j)`,
      measure: { threadId, outboundCount: outbound.length, inboundCount: 0, spanDays: Math.round(spanDays) },
      detectorVersion: DETECTOR_VERSION, confidence: 0.9, status: 'accepted',
    })
  }
  return out
}

// ── R01 : latence asymétrique du contact vs SA baseline (jamais un seuil absolu) ──
export function detectR01(baseline: DyadBaseline, recentMessages: DyadMessage[], nowMs: number, recentDays = 45): MarkerEventDraft[] {
  if (!baseline.sufficient || baseline.contactResponseMedianHours == null) return []
  const from = nowMs - recentDays * DAY
  const byThread = new Map<string, DyadMessage[]>()
  for (const m of recentMessages) if (new Date(m.sentAt).getTime() >= from) byThread.set(m.threadId, [...(byThread.get(m.threadId) ?? []), m])
  const recent: number[] = []
  let lastId = ''
  for (const arr of byThread.values()) {
    const s = arr.sort((a, b) => new Date(a.sentAt).getTime() - new Date(b.sentAt).getTime())
    for (let i = 1; i < s.length; i++) {
      if (s[i - 1]!.direction === 'outbound' && s[i]!.direction === 'inbound') {
        recent.push((new Date(s[i]!.sentAt).getTime() - new Date(s[i - 1]!.sentAt).getTime()) / 3_600_000)
        lastId = s[i]!.id
      }
    }
  }
  const recentMed = median(recent)
  if (recentMed == null || recent.length < 2) return []
  const ratio = recentMed / baseline.contactResponseMedianHours
  let sense: -1 | 1 | 0 = 0
  if (ratio >= 1.5) sense = -1        // le contact répond nettement plus lentement qu'à son habitude
  else if (ratio <= 0.67) sense = 1   // nettement plus vite
  if (sense === 0) return []
  return [{
    markerId: 'R01', scope: 'person', sense, observedAt: new Date(nowMs).toISOString(),
    evidenceRef: lastId,
    evidenceText: `Latence de réponse du contact ${sense < 0 ? 'dégradée' : 'améliorée'} (${recentMed.toFixed(0)}h vs baseline ${baseline.contactResponseMedianHours.toFixed(0)}h)`,
    measure: { baselineHours: baseline.contactResponseMedianHours, recentHours: recentMed, ratio: Number(ratio.toFixed(2)) },
    detectorVersion: DETECTOR_VERSION, confidence: 0.75, status: 'accepted',
  }]
}

// ── R02 : initiation qualifiée (candidate — « substantielle vs relance » exige le contenu) ──
export function detectR02(messages: DyadMessage[], nowMs: number, recentDays = 90): MarkerEventDraft[] {
  const from = nowMs - recentDays * DAY
  const byThread = new Map<string, DyadMessage[]>()
  for (const m of messages) byThread.set(m.threadId, [...(byThread.get(m.threadId) ?? []), m])
  let inboundStarts = 0
  let firstInboundId = ''
  for (const arr of byThread.values()) {
    const s = arr.sort((a, b) => new Date(a.sentAt).getTime() - new Date(b.sentAt).getTime())
    const first = s[0]!
    if (first.direction === 'inbound' && new Date(first.sentAt).getTime() >= from) { inboundStarts++; if (!firstInboundId) firstInboundId = first.id }
  }
  if (inboundStarts === 0) return []
  return [{
    markerId: 'R02', scope: 'person', sense: 1, observedAt: new Date(nowMs).toISOString(),
    evidenceRef: firstInboundId,
    evidenceText: `${inboundStarts} fil(s) initié(s) par le contact — substance à confirmer (contenu non stocké)`,
    measure: { inboundThreadStarts: inboundStarts },
    detectorVersion: DETECTOR_VERSION, confidence: 0.5, status: 'candidate',
  }]
}

// ── A01 : diversité de canaux instrumentés actifs (déterministe, bipolaire) ──
export function detectA01(messages: DyadMessage[], meetings: DyadMeeting[], nowMs: number, windowDays = 182): MarkerEventDraft[] {
  const from = nowMs - windowDays * DAY
  const hasEmail = messages.some((m) => new Date(m.sentAt).getTime() >= from && new Date(m.sentAt).getTime() <= nowMs)
  const hasMeeting = meetings.some((m) => m.occurred && m.contactParticipated && (!m.state || m.state === 'observed') && new Date(m.startsAt).getTime() >= from && new Date(m.startsAt).getTime() <= nowMs)
  const channels = [hasEmail && 'email', hasMeeting && 'meeting'].filter(Boolean) as string[]
  if (channels.length === 0) return []
  const sense: -1 | 1 = channels.length >= 2 ? 1 : -1
  return [{
    markerId: 'A01', scope: 'person', sense, observedAt: new Date(nowMs).toISOString(),
    evidenceRef: 'channels',
    evidenceText: `${channels.length} canal/canaux actif(s) : ${channels.join(', ')}`,
    measure: { channelCount: channels.length, channels },
    detectorVersion: DETECTOR_VERSION, confidence: 0.8, status: 'accepted',
  }]
}

// ── A02 : continuité entre périodes (trimestres actifs, déterministe, bipolaire) ──
export function detectA02(messages: DyadMessage[], meetings: DyadMeeting[], nowMs: number): MarkerEventDraft[] {
  const times = [...messages.map((m) => new Date(m.sentAt).getTime()), ...meetings.filter(m => m.occurred && m.contactParticipated && (!m.state || m.state === 'observed')).map((m) => new Date(m.startsAt).getTime())]
  const activeQuarters = new Set<number>()
  for (let q = 0; q < 4; q++) {
    const start = nowMs - (q + 1) * 90 * DAY, end = nowMs - q * 90 * DAY
    if (times.some((t) => t > start && t <= end)) activeQuarters.add(q)
  }
  const n = activeQuarters.size
  if (n === 0) return []
  let sense: -1 | 1 | 0 = 0
  if (n >= 3) sense = 1
  else if (n <= 1) sense = -1
  if (sense === 0) return []
  return [{
    markerId: 'A02', scope: 'person', sense, observedAt: new Date(nowMs).toISOString(),
    evidenceRef: 'continuity',
    evidenceText: `${n}/4 trimestres actifs sur 12 mois`,
    measure: { activeQuarters: n },
    detectorVersion: DETECTOR_VERSION, confidence: 0.75, status: 'accepted',
  }]
}

// ── E05 : acceptation de sollicitations → CANDIDATE (pas d'accept/decline capté) ──
export function detectE05Candidate(meetings: DyadMeeting[]): MarkerEventDraft[] {
  const held = meetings.filter((m) => m.occurred && m.contactParticipated && (!m.state || m.state === 'observed'))
  if (held.length === 0) return []
  const last = held.sort((a, b) => new Date(b.startsAt).getTime() - new Date(a.startsAt).getTime())[0]!
  return [{
    markerId: 'E05', scope: 'person', sense: 1, observedAt: last.startsAt,
    evidenceRef: last.id,
    evidenceText: `${held.length} réunion(s) tenue(s) avec le contact — acceptation présumée (statut accept/decline non capté)`,
    measure: { heldMeetings: held.length },
    detectorVersion: DETECTOR_VERSION, confidence: 0.5, status: 'candidate',
  }]
}

/** Orchestrateur : tous les détecteurs déterministes disponibles pour une dyade. */
export function runDeterministicDetectors(messages: DyadMessage[], meetings: DyadMeeting[], nowMs: number): { baseline: DyadBaseline; drafts: MarkerEventDraft[] } {
  messages = messages.filter(m => new Date(m.sentAt).getTime() <= nowMs)
  meetings = meetings.filter(m => new Date(m.startsAt).getTime() <= nowMs && m.occurred && m.contactParticipated && (!m.state || m.state === 'observed'))
  const baseline = computeDyadBaseline(messages, meetings, nowMs)
  const drafts = [
    ...detectS04(messages),
    ...detectR01(baseline, messages, nowMs),
    ...detectR02(messages, nowMs),
    ...detectA01(messages, meetings, nowMs),
    ...detectA02(messages, meetings, nowMs),
    ...detectE05Candidate(meetings),
  ]
  return { baseline, drafts }
}
"}]}

